/* Manager Concentration data engine — built from window.FD (real tenant export).
   Managers = fund families (+ Direct Equities bucket); products = the actual
   securities held; "teams" = the firm's 30 advisors. Cash sweep excluded. */
(function () {
  var FD = window.FD;
  var TEAMS = FD.advisors.map(a => ({
    name: a.nm,
    short: a.crd
  }));
  var crdIdx = {};
  TEAMS.forEach((t, i) => crdIdx[t.short] = i);
  var managers = [],
    products = [];
  var famMap = new Map();
  FD.secs.filter(s => s.tk !== 'CASH').forEach(s => {
    var m = famMap.get(s.fam);
    if (!m) {
      m = {
        id: managers.length,
        name: s.fam,
        aum: 0,
        flows: 0,
        hh: 0,
        prods: []
      };
      famMap.set(s.fam, m);
      managers.push(m);
    }
    var advMV = s.adv || {};
    var tw = TEAMS.map(t => advMV[t.short] || 0);
    var wsum = tw.reduce((a, b) => a + b, 0) || 1;
    tw = tw.map(w => Math.max(0, w) / wsum);
    var aumM = s.mv / 1e6,
      flowsM = s.flow / 1e6,
      glM = s.gl / 1e6;
    /* ease of consolidation: inverse of embedded-gain ratio (real G/L from tax lots) */
    var gainRatio = Math.max(0, s.gl / Math.max(s.mv, 1));
    var ease = Math.min(0.9, Math.max(0.08, 0.85 - 3 * gainRatio));
    var p = {
      id: products.length,
      mgrId: m.id,
      name: s.nm + ' (' + s.tk + ')',
      tk: s.tk,
      veh: s.ty === 'ETF' ? 'ETF' : 'STK',
      sec: s.sec,
      aum: aumM,
      hh: s.hh,
      pos: s.accts,
      flows: flowsM,
      gl: glM,
      ease,
      tw,
      teams: tw.filter(w => w > 0.001).length,
      models: []
    };
    products.push(p);
    m.prods.push(p.id);
    m.aum += aumM;
    m.flows += flowsM;
  });
  managers.forEach(m => {
    var hs = new Set();
    m.prods.forEach(id => {});
    m.hh = Math.round(m.prods.reduce((s, id) => s + products[id].hh, 0) * (m.prods.length > 1 ? 0.6 : 1));
  });
  var TOTAL = managers.reduce((s, m) => s + m.aum, 0);

  /* flags computed over a filtered product set */
  function detect(prodOk) {
    var tail = new Set(),
      outl = new Set();
    managers.forEach(m => {
      var ps = m.prods.map(id => products[id]).filter(prodOk);
      if (!ps.length) return;
      var aum = ps.reduce((s, p) => s + p.aum, 0);
      if (aum / TOTAL < 0.012 && m.name !== 'Direct Equities') {
        tail.add(m.id);
        return;
      }
      var famAum = ps.reduce((s, p) => s + p.aum, 0);
      ps.forEach(p => {
        if (p.aum / famAum < 0.009 && p.aum < 3) outl.add(p.id);
      });
    });
    return {
      tail,
      outl
    };
  }
  function buildTargets(det, wFn) {
    var t = [];
    det.tail.forEach(mi => {
      var m = managers[mi];
      var ps = m.prods.map(id => products[id]);
      var aum = ps.reduce((s, p) => s + p.aum * wFn(p), 0);
      if (aum < 0.01) return;
      var hh = Math.max(1, Math.round(ps.reduce((s, p) => s + p.hh * wFn(p), 0)));
      var core = m.name === 'SPDR (State Street)' ? 'iShares Core S&P 500 (IVV)' : 'Vanguard / iShares core lineup';
      t.push({
        type: 'mgr',
        mgrId: mi,
        prodId: null,
        name: m.name,
        sub: ps.length + ' product' + (ps.length > 1 ? 's' : '') + ' · duplicates core index exposure',
        aum,
        hh,
        teams: Math.max(...ps.map(p => p.teams)),
        pos: Math.max(1, Math.round(ps.reduce((s, p) => s + p.pos * wFn(p), 0))),
        flows: ps.reduce((s, p) => s + p.flows * wFn(p), 0),
        easy: ps.reduce((s, p) => s + p.aum * p.ease * wFn(p), 0),
        locked: false,
        action: [['Exit family — consolidate into ', 0], [core, 1], [' (same exposure, existing core partner)', 0]]
      });
    });
    det.outl.forEach(pi => {
      var p = products[pi];
      if (det.tail.has(p.mgrId)) return;
      var aum = p.aum * wFn(p);
      if (aum < 0.01) return;
      var m = managers[p.mgrId];
      t.push({
        type: 'prod',
        mgrId: p.mgrId,
        prodId: pi,
        name: p.name,
        sub: m.name + ' · ' + p.hh + ' households hold a sliver',
        aum,
        hh: Math.max(1, Math.round(p.hh * wFn(p))),
        teams: p.teams,
        pos: Math.max(1, Math.round(p.pos * wFn(p))),
        flows: p.flows * wFn(p),
        easy: p.aum * p.ease * wFn(p),
        locked: false,
        action: p.veh === 'STK' ? [['Thinly-held single stock — fold into ', 0], ['Vanguard Total Stock Market (VTI)', 1]] : [['Fold into the comparable core index fund clients already own', 0]]
      });
    });
    return t.sort((a, b) => b.aum - a.aum);
  }
  var fm = v => {
    var a = Math.abs(v),
      s = v < 0 ? '−' : '';
    return a >= 1000 ? s + '$' + (a / 1000).toFixed(2) + 'B' : a >= 1 ? s + '$' + a.toFixed(1) + 'M' : s + '$' + Math.round(a * 1000) + 'K';
  };
  var fpct = (v, d = 1) => (v * 100).toFixed(d) + '%';
  window.MC = {
    TEAMS,
    managers,
    products,
    TOTAL,
    detect,
    buildTargets,
    fm,
    fpct
  };
})();
;
