/* ---- value formatting ---- */
function trimNum(v) {
  var r = Math.round(v * 10) / 10;
  return Number.isInteger(r) ? r.toString() : r.toFixed(1);
}
function fmtGoal(v, fmt) {
  if (v == null || isNaN(v)) return '—';
  if (fmt === '$M') return '$' + trimNum(v) + 'M';
  if (fmt === '$K') return '$' + trimNum(v) + 'K';
  if (fmt === '%') return trimNum(v) + '%';
  return Math.round(v).toLocaleString();
}

/* ---- progress + pacing ---- */
function goalProgress(g) {
  var span = g.dir === 'down' ? g.start - g.target : g.target - g.start;
  if (!span) return 1;
  var done = g.dir === 'down' ? g.start - g.current : g.current - g.start;
  return Math.max(0, done / span);
}
function goalPace(g) {
  var s = new Date(g.periodStart || g.deadline).getTime();
  var e = new Date(g.deadline).getTime();
  var now = Date.now();
  if (!e || e <= s) return 1;
  return Math.max(0, Math.min(1, (now - s) / (e - s)));
}
function goalStatus(g) {
  var p = goalProgress(g);
  if (p >= 1) return {
    label: 'Achieved',
    badge: 'green',
    fill: 'rgb(94,214,164)',
    icon: 'circle-check'
  };
  var diff = p - goalPace(g);
  if (diff >= 0.05) return {
    label: 'Ahead',
    badge: 'teal',
    fill: 'rgb(120,200,210)'
  };
  if (diff >= -0.05) return {
    label: 'On track',
    badge: 'green',
    fill: 'rgb(94,214,164)'
  };
  if (diff >= -0.18) return {
    label: 'At risk',
    badge: 'amber',
    fill: 'rgb(245,200,90)'
  };
  return {
    label: 'Behind',
    badge: 'red',
    fill: 'rgb(248,113,113)'
  };
}
